mapper.select:
	SELECT SUM(CREAT_CO) AS statsCo


	     , SUBSTR(OCCRRNC_DE, 1, 4) AS statsDate



	     , CONCAT(CONCAT(SUBSTR(OCCRRNC_DE, 1, 4), '-'), SUBSTR(OCCRRNC_DE, 5, 2)) AS statsDate



	     , CONCAT(CONCAT(CONCAT(CONCAT(SUBSTR(OCCRRNC_DE, 1, 4), '-'), SUBSTR(OCCRRNC_DE, 5, 2)), '-'), SUBSTR(OCCRRNC_DE, 7, 2)) AS statsDate

	  FROM SBBSSUMMARY
 	 WHERE 1 = 1

	   AND OCCRRNC_DE BETWEEN #{fromDate} AND #{toDate}
	   AND STATS_SE = #{statsKind}

	   AND DETAIL_STATS_SE = #{detailStatsKind}

	 GROUP BY statsDate

SELECT a.OCCRRNC_DE AS statsDate , a.TOP_INQIRE_BBSCTT_ID AS mxmmInqireBbsId , b.NTT_SJ AS mxmmInqireBbsNm , b.RDCNT AS maxStatsCo FROM ( SELECT OCCRRNC_DE , TOP_INQIRE_BBSCTT_ID FROM SBBSSUMMARY WHERE 1 = 1 AND OCCRRNC_DE BETWEEN #{fromDate} AND #{toDate} AND STATS_SE = #{statsKind}
AND DETAIL_STATS_SE = #{detailStatsKind}
) a, NBBS b WHERE a.TOP_INQIRE_BBSCTT_ID = to_char(b.NTT_ID, 'FM9999999999999') ORDER BY statsDate

SELECT a.OCCRRNC_DE AS statsDate , a.MUMM_INQIRE_BBSCTT_ID AS mummInqireBbsId , b.NTT_SJ AS mummInqireBbsNm , b.RDCNT AS minStatsCo FROM ( SELECT OCCRRNC_DE , MUMM_INQIRE_BBSCTT_ID FROM SBBSSUMMARY WHERE 1 = 1 AND OCCRRNC_DE BETWEEN #{fromDate} AND #{toDate} AND STATS_SE = #{statsKind}
AND DETAIL_STATS_SE = #{detailStatsKind}
) a, NBBS b WHERE a.MUMM_INQIRE_BBSCTT_ID = to_char(b.NTT_ID, 'FM9999999999999') ORDER BY statsDate

SELECT a.OCCRRNC_DE AS statsDate , a.TOP_NTCR_ID AS topNtcepersonId , COUNT(b.NTT_ID) AS topNtcepersonCo FROM ( SELECT OCCRRNC_DE , TOP_NTCR_ID FROM SBBSSUMMARY WHERE 1 = 1 AND OCCRRNC_DE BETWEEN #{fromDate} AND #{toDate} AND STATS_SE = #{statsKind}
AND DETAIL_STATS_SE = #{detailStatsKind}
) a, NBBS b WHERE 1=1
AND a.TOP_NTCR_ID IS NOT NULL AND b.NTCR_ID = a.TOP_NTCR_ID
AND b.NTCR_ID IS NOT NULL GROUP BY statsDate, topNtcepersonId ORDER BY statsDate


SELECT a.STATS_SE AS statsKind
  FROM SBBSSUMMARY a
 WHERE a.OCCRRNC_DE = TO_CHAR(NOW() - interval '1 day', 'YYYYmmdd')
   AND a.STATS_SE = #{statsKind}
   AND a.DETAIL_STATS_SE = #{detailStatsKind}
